DROP TABLE IF EXISTS `rpbcalendar_billing_transactions`;
CREATE TABLE `rpbcalendar_billing_transactions` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `uuid` char(32) NOT NULL,
  `company_id` int(10) unsigned NOT NULL,
  `plan_id` int(10) unsigned NOT NULL,
  `kind` enum('new','renewal','upgrade') NOT NULL DEFAULT 'new',
  `amount` decimal(10,2) NOT NULL,
  `list_amount` decimal(10,2) DEFAULT NULL,
  `discount_amount` decimal(10,2) DEFAULT NULL,
  `promo_ids` varchar(255) DEFAULT NULL,
  `coupon_code` varchar(30) DEFAULT NULL,
  `currency` char(3) NOT NULL,
  `status` enum('pending','paid','failed','cancelled','refunded') NOT NULL DEFAULT 'pending',
  `provider` varchar(20) NOT NULL,
  `provider_session` varchar(255) DEFAULT NULL,
  `provider_ref` varchar(255) DEFAULT NULL,
  `checkout_url` text DEFAULT NULL,
  `period_start` datetime DEFAULT NULL,
  `period_end` datetime DEFAULT NULL,
  `failure_reason` varchar(255) DEFAULT NULL,
  `created_by` int(10) unsigned DEFAULT NULL,
  `created` datetime DEFAULT NULL,
  `paid_at` datetime DEFAULT NULL,
  `modified` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uuid` (`uuid`),
  UNIQUE KEY `provider_session` (`provider`,`provider_session`),
  UNIQUE KEY `provider_ref` (`provider`,`provider_ref`),
  KEY `company_status` (`company_id`,`status`)
) ENGINE=InnoDB AUTO_INCREMENT=14 DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci;


DROP TABLE IF EXISTS `rpbcalendar_billing_webhook_events`;
CREATE TABLE `rpbcalendar_billing_webhook_events` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
